import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
// IMPORT CÁC API SERVICE VÀO ĐÂY NÈ BỐ:
import { cartsApi, couponsApi } from '../services/api';

const Cart = () => {
    // Khởi tạo công cụ chuyển trang
    const navigate = useNavigate();

    // 1. STATE LƯU GIỎ HÀNG & MÃ GIẢM GIÁ
    const [cart, setCart] = useState([]);
    const [couponCode, setCouponCode] = useState('');
    const [discount, setDiscount] = useState(0);

    // 2. TỰ ĐỘNG GỌI API LẤY GIỎ HÀNG CỦA NGƯỜI ĐĂNG NHẬP KHI MỞ TRANG
    useEffect(() => {
        // ✅ LẤY ID KHÁCH HÀNG THỰC TẾ
        const userData = JSON.parse(localStorage.getItem('user') || '{}');
        const currentUserId = userData.userId || userData.id;

        if (currentUserId) {
            // Thay fetch bằng cartsApi
            cartsApi.getByUserId(currentUserId)
                .then(res => {
                    // Lấy được data từ API thì nhét vào state (Axios trả về trong res.data)
                    setCart(res.data);
                })
                .catch(err => console.log("Lỗi tải giỏ hàng: ", err));
        } else {
            // Khách chưa đăng nhập thì giỏ hàng trống
            setCart([]);
        }
    }, []);

    // 3. HÀM TĂNG GIẢM SỐ LƯỢNG (Tạm thời xử lý trên giao diện)
    const handleQuantityChange = (itemId, change) => {
        setCart(cart.map(item => {
            if (item.id === itemId) {
                const newQuantity = item.quantity + change;
                return { ...item, quantity: newQuantity > 0 ? newQuantity : 1 }; // Không cho giảm xuống 0
            }
            return item;
        }));
    };

    // 4. HÀM XÓA MÓN HÀNG (ĐÃ NÂNG CẤP GỌI API BẰNG SERVICE)
    const handleRemove = async (itemId) => {
        if (window.confirm("Ní có chắc muốn bỏ món này ra khỏi giỏ không? 🛒")) {
            try {
                // Phóng API chém thẳng xuống backend thông qua cartsApi
                await cartsApi.removeFromCart(itemId);

                // Nếu API báo đã xóa thành công (không nhảy vào catch), thì mình lọc nó ra khỏi màn hình React
                setCart(cart.filter(item => item.id !== itemId));

            } catch (error) {
                console.error("Lỗi kết nối mất tiêu:", error);
                alert("Á đù, có lỗi gì đó, xóa không được ní ơi!");
            }
        }
    };

    // 5. HÀM TÍNH TỔNG TIỀN TỰ ĐỘNG
    const subtotal = cart.reduce((total, item) => {
        // Ưu tiên giá giảm, không có thì lấy giá gốc
        const priceToUse = item.discountPrice || item.price;
        return total + (priceToUse * item.quantity);
    }, 0);

    const shippingFee = 0; // BỎ TÍNH PHÍ SHIP Ở ĐÂY, SẼ TÍNH Ở CHECKOUT
    const totalAmount = subtotal - discount; // Đã trừ đi tiền giảm giá

    // 6. HÀM GỌI API KIỂM TRA MÃ GIẢM GIÁ (DÙNG COUPONSAPI)
    const handleApplyCoupon = async () => {
        if (!couponCode) {
            alert("Ní chưa nhập mã mà đòi giảm giá gì!");
            return;
        }

        try {
            const response = await couponsApi.check(couponCode);
            // Axios gom dữ liệu vào response.data
            const data = response.data;
            const phanTramGiam = data.discountPercent / 100;
            setDiscount(subtotal * phanTramGiam);
            alert(`Áp dụng thành công mã giảm ${data.discountPercent}%! 🌟`);

        } catch (error) {
            console.error("Lỗi:", error);
            setDiscount(0);
            // Lấy thông báo lỗi từ backend C# quăng ra
            alert(error.response?.data || "Mã giảm giá không hợp lệ!");
        }
    };

    // 7. HÀM CHUYỂN TRANG THANH TOÁN
    const handleProceedCheckout = () => {
        if (cart.length === 0) {
            alert("Giỏ hàng đang trống, mua thêm đồ đi ní!");
            return;
        }

        // 🌟 BẪY BẢO VỆ: CHƯA ĐĂNG NHẬP THÌ KHÔNG CHO CHECKOUT
        const userData = JSON.parse(localStorage.getItem('user') || '{}');
        const currentUserId = userData.userId || userData.id;

        if (!currentUserId) {
            alert("Vui lòng đăng nhập để tiến hành thanh toán!");
            navigate('/login');
            return;
        }

        // Gói ghém toàn bộ tiền bạc và mã giảm giá ném sang trang Checkout
        navigate('/checkout', {
            state: {
                subtotal: subtotal,
                shipping: shippingFee,
                discount: discount,
                total: totalAmount,
                cartItems: cart,
                couponCode: couponCode
            }
        });
    };

    return (
        <>
            {/* Navbar start */}
            <div className="container-fluid fixed-top">
                <div className="container topbar bg-primary d-none d-lg-block">
                    <div className="d-flex justify-content-between">
                        <div className="top-info ps-2">
                            <small className="me-3"><i className="fas fa-map-marker-alt me-2 text-secondary"></i> <a href="#" className="text-white">236, Hoàng Quốc Việt, Hà Nội</a></small>
                            <small className="me-3"><i className="fas fa-envelope me-2 text-secondary"></i><a href="#" className="text-white">Email@Example.com</a></small>
                        </div>
                        <div className="top-link pe-2">
                            <a href="#" className="text-white"><small className="text-white mx-2">Chính sách bảo mật</small>/</a>
                            <a href="#" className="text-white"><small className="text-white mx-2">Điều khoản sử dụng</small>/</a>
                            <a href="#" className="text-white"><small className="text-white ms-2">Bán hàng & Hoàn tiền</small></a>
                        </div>
                    </div>
                </div>
                <div className="container px-0">
                    <nav className="navbar navbar-light bg-white navbar-expand-xl">
                        <Link to="/" className="navbar-brand"><h1 className="text-primary display-6">Fruitables</h1></Link>
                        <button className="navbar-toggler py-2 px-3" type="button" data-bs-toggle="collapse" data-bs-target="#navbarCollapse">
                            <span className="fa fa-bars text-primary"></span>
                        </button>
                        <div className="collapse navbar-collapse bg-white" id="navbarCollapse">
                            <div className="navbar-nav mx-auto">
                                <Link to="/" className="nav-item nav-link">Trang chủ</Link>
                                <Link to="/shop" className="nav-item nav-link">Cửa hàng</Link>
                                <Link to="/shop-detail" className="nav-item nav-link">Chi tiết sản phẩm</Link>
                                <div className="nav-item dropdown">
                                    <a href="#" className="nav-link dropdown-toggle active" data-bs-toggle="dropdown">Trang</a>
                                    <div className="dropdown-menu m-0 bg-secondary rounded-0">
                                        <Link to="/cart" className="dropdown-item active">Giỏ hàng</Link>
                                        <Link to="/checkout" className="dropdown-item">Thanh toán</Link>

                                    </div>
                                </div>
                                <Link to="/contact" className="nav-item nav-link">Liên hệ</Link>
                            </div>
                            <div className="d-flex m-3 me-0">
                                <button className="btn-search btn border border-secondary btn-md-square rounded-circle bg-white me-4" data-bs-toggle="modal" data-bs-target="#searchModal"><i className="fas fa-search text-primary"></i></button>
                                <Link to="/cart" className="position-relative me-4 my-auto">
                                    <i className="fa fa-shopping-bag fa-2x"></i>
                                    {/* Hiển thị linh hoạt số món đồ trong giỏ */}
                                    <span className="position-absolute bg-secondary rounded-circle d-flex align-items-center justify-content-center text-dark px-1" style={{ top: '-5px', left: '15px', height: '20px', minWidth: '20px' }}>{cart.length}</span>
                                </Link>
                                {/* LOGIC HIỂN THỊ MENU ĐĂNG NHẬP THÔNG MINH */}
                                {(() => {
                                    const userStorage = localStorage.getItem('user');
                                    let currentUser = null;
                                    if (userStorage && userStorage !== "undefined" && userStorage !== "null") {
                                        try {
                                            currentUser = JSON.parse(userStorage);
                                        } catch (e) {
                                            console.error("Lỗi đọc user", e);
                                        }
                                    }

                                    if (currentUser) {
                                        return (
                                            <div className="nav-item dropdown my-auto">
                                                <a href="#" className="nav-link dropdown-toggle d-flex align-items-center" data-bs-toggle="dropdown" style={{ padding: 0 }}>
                                                    <i className="fas fa-user fa-2x text-success"></i>
                                                    <span className="ms-2 fw-bold text-dark">{currentUser.name || currentUser.userName}</span>
                                                </a>
                                                <div className="dropdown-menu m-0 bg-secondary rounded-0">
                                                    {/* NẾU LÀ ADMIN THÌ HIỆN NÚT VÀO DASHBOARD */}
                                                    {(currentUser.role === 'Admin' || currentUser.Role === 'Admin') && (
                                                        <Link to="/dashboard" className="dropdown-item fw-bold text-warning">
                                                            <i className="fas fa-cog me-2"></i>Vào trang Quản trị
                                                        </Link>
                                                    )}
                                                    <Link to="/my-orders" className="dropdown-item">Đơn hàng của tôi</Link>
                                                    <a href="#" className="dropdown-item" onClick={(e) => {
                                                        e.preventDefault();
                                                        localStorage.clear(); // Xóa sạch bộ nhớ
                                                        window.location.href = '/'; // Đá về trang chủ
                                                    }}>
                                                        <i className="fas fa-sign-out-alt me-2"></i>Đăng xuất
                                                    </a>
                                                </div>
                                            </div>
                                        );
                                    } else {
                                        // NẾU CHƯA ĐĂNG NHẬP THÌ HIỆN NÚT LOGIN BÌNH THƯỜNG
                                        return (
                                            <Link to="/login" className="my-auto">
                                                <i className="fas fa-user fa-2x"></i>
                                            </Link>
                                        );
                                    }
                                })()}
                            </div>
                        </div>
                    </nav>
                </div>
            </div>
            {/* Navbar End */}

            {/* Modal Search Start (Giữ nguyên) */}
            <div className="modal fade" id="searchModal" tabIndex="-1" aria-labelledby="exampleModalLabel" aria-hidden="true">
                <div className="modal-dialog modal-fullscreen">
                    <div className="modal-content rounded-0">
                        <div className="modal-header">
                            <h5 className="modal-title" id="exampleModalLabel">Tìm kiếm bằng từ khóa</h5>
                            <button type="button" className="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
                        </div>
                        <div className="modal-body d-flex align-items-center">
                            <div className="input-group w-75 mx-auto d-flex">
                                <input type="search" className="form-control p-3" placeholder="Từ khóa..." aria-describedby="search-icon-1" />
                                <span id="search-icon-1" className="input-group-text p-3"><i className="fa fa-search"></i></span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Single Page Header start */}
            <div className="container-fluid page-header py-5">
                <h1 className="text-center text-white display-6">Giỏ hàng</h1>
                <ol className="breadcrumb justify-content-center mb-0">
                    <li className="breadcrumb-item"><Link to="/">Trang chủ</Link></li>
                    <li className="breadcrumb-item"><a href="#">Trang</a></li>
                    <li className="breadcrumb-item active text-white">Giỏ hàng</li>
                </ol>
            </div>
            {/* Single Page Header End */}

            {/* Cart Page Start */}
            <div className="container-fluid py-5">
                <div className="container py-5">
                    <div className="table-responsive">
                        <table className="table">
                            <thead>
                                <tr>
                                    <th scope="col">Hình ảnh</th>
                                    <th scope="col">Tên sản phẩm</th>
                                    <th scope="col">Đơn giá</th>
                                    <th scope="col">Số lượng</th>
                                    <th scope="col">Thành tiền</th>
                                    <th scope="col">Thao tác</th>
                                </tr>
                            </thead>
                            <tbody>
                                {/* LỌC DỮ LIỆU Ở ĐÂY NÈ NÍ */}
                                {cart.length === 0 ? (
                                    <tr>
                                        <td colSpan="6" className="text-center py-5">
                                            <h4 className="text-secondary">Giỏ hàng của ní đang trống trơn! 🛒</h4>
                                            <Link to="/shop" className="btn btn-primary mt-3 rounded-pill px-4 py-2 text-white">Đi mua sắm ngay</Link>
                                        </td>
                                    </tr>
                                ) : (
                                    cart.map((item) => {
                                        // Ưu tiên giá giảm
                                        const priceToUse = item.discountPrice || item.price;
                                        return (
                                            <tr key={item.id}>
                                                <th scope="row">
                                                    <div className="d-flex align-items-center">
                                                        <img src={item.imageUrl || '/img/avatar.jpg'} className="img-fluid me-5 rounded-circle" style={{ width: '80px', height: '80px', objectFit: 'cover' }} alt={item.name} />
                                                    </div>
                                                </th>
                                                <td>
                                                    <p className="mb-0 mt-4">{item.name}</p>
                                                </td>
                                                <td>
                                                    <p className="mb-0 mt-4">${priceToUse.toFixed(2)}</p>
                                                </td>
                                                <td>
                                                    <div className="input-group quantity mt-4" style={{ width: '100px' }}>
                                                        <div className="input-group-btn">
                                                            {/* Nút Trừ */}
                                                            <button onClick={() => handleQuantityChange(item.id, -1)} className="btn btn-sm btn-minus rounded-circle bg-light border">
                                                                <i className="fa fa-minus"></i>
                                                            </button>
                                                        </div>
                                                        <input type="text" className="form-control form-control-sm text-center border-0" value={item.quantity} readOnly />
                                                        <div className="input-group-btn">
                                                            {/* Nút Cộng */}
                                                            <button onClick={() => handleQuantityChange(item.id, 1)} className="btn btn-sm btn-plus rounded-circle bg-light border">
                                                                <i className="fa fa-plus"></i>
                                                            </button>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td>
                                                    <p className="mb-0 mt-4">${(priceToUse * item.quantity).toFixed(2)}</p>
                                                </td>
                                                <td>
                                                    {/* Nút Xóa */}
                                                    <button onClick={() => handleRemove(item.id)} className="btn btn-md rounded-circle bg-light border mt-4">
                                                        <i className="fa fa-times text-danger"></i>
                                                    </button>
                                                </td>
                                            </tr>
                                        )
                                    })
                                )}
                            </tbody>
                        </table>
                    </div>

                    {/* KHU VỰC TÍNH TIỀN TỰ ĐỘNG */}
                    <div className="mt-5">
                        <input
                            type="text"
                            className="border-0 border-bottom rounded me-5 py-3 mb-4"
                            placeholder="Nhập mã giảm giá..."
                            value={couponCode}
                            onChange={(e) => setCouponCode(e.target.value)}
                        />
                        <button className="btn border-secondary rounded-pill px-4 py-3 text-primary" type="button" onClick={handleApplyCoupon}>Áp dụng mã</button>
                    </div>
                    <div className="row g-4 justify-content-end">
                        <div className="col-8"></div>
                        <div className="col-sm-8 col-md-7 col-lg-6 col-xl-4">
                            <div className="bg-light rounded">
                                <div className="p-4">
                                    <h1 className="display-6 mb-4">Tổng <span className="fw-normal">Giỏ Hàng</span></h1>
                                    <div className="d-flex justify-content-between mb-4">
                                        <h5 className="mb-0 me-4">Tạm tính:</h5>
                                        <p className="mb-0">${subtotal.toFixed(2)}</p>
                                    </div>
                                    <div className="d-flex justify-content-between">
                                        <h5 className="mb-0 me-4">Phí vận chuyển:</h5>
                                        <div className="">
                                            <p className="mb-0 text-primary">Sẽ tính ở bước Thanh toán</p>
                                        </div>
                                    </div>

                                    {/* HIỂN THỊ TIỀN ĐƯỢC GIẢM KHI NHẬP MÃ THÀNH CÔNG */}
                                    {discount > 0 && (
                                        <div className="d-flex justify-content-between text-success mt-3">
                                            <h5 className="mb-0 me-4">Giảm giá ({couponCode})</h5>
                                            <p className="mb-0">-${discount.toFixed(2)}</p>
                                        </div>
                                    )}

                                </div>
                                <div className="py-4 mb-4 border-top border-bottom d-flex justify-content-between">
                                    <h5 className="mb-0 ps-4 me-4">Thành tiền:</h5>
                                    <p className="mb-0 pe-4 fw-bold">${totalAmount.toFixed(2)}</p>
                                </div>

                                {/* NÚT BẤM SANG TRANG CHECKOUT ĐÃ CẮM ĐIỆN */}
                                <button className="btn border-secondary rounded-pill px-4 py-3 text-primary text-uppercase mb-4 ms-4" type="button" onClick={handleProceedCheckout}>
                                    Tiến hành Thanh toán
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            {/* Cart Page End */}

            {/* Footer Start */}
            <div className="container-fluid bg-dark text-white-50 footer pt-5 mt-5">
                <div className="container py-5">
                    <div className="pb-4 mb-4" style={{ borderBottom: '1px solid rgba(226, 175, 24, 0.5)' }}>
                        <div className="row g-4">
                            <div className="col-lg-3">
                                <a href="#">
                                    <h1 className="text-primary mb-0">Fruitables</h1>
                                    <p className="text-secondary mb-0">Sản phẩm tươi sạch nhất</p>
                                </a>
                            </div>
                            <div className="col-lg-6">
                                <div className="position-relative mx-auto">
                                    <input className="form-control border-0 w-100 py-3 px-4 rounded-pill" type="email" placeholder="Email của bạn" />
                                    <button type="submit" className="btn btn-primary border-0 border-secondary py-3 px-4 position-absolute rounded-pill text-white" style={{ top: 0, right: 0 }}>Đăng ký ngay</button>
                                </div>
                            </div>
                            <div className="col-lg-3">
                                <div className="d-flex justify-content-end pt-3">
                                    <a className="btn btn-outline-secondary me-2 btn-md-square rounded-circle" href=""><i className="fab fa-twitter"></i></a>
                                    <a className="btn btn-outline-secondary me-2 btn-md-square rounded-circle" href=""><i className="fab fa-facebook-f"></i></a>
                                    <a className="btn btn-outline-secondary me-2 btn-md-square rounded-circle" href=""><i className="fab fa-youtube"></i></a>
                                    <a className="btn btn-outline-secondary btn-md-square rounded-circle" href=""><i className="fab fa-linkedin-in"></i></a>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div className="row g-5">
                        <div className="col-lg-3 col-md-6">
                            <div className="footer-item">
                                <h4 className="text-light mb-3">Vì sao chọn chúng tôi!</h4>
                                <p className="mb-4">Chúng tôi cam kết mang đến thực phẩm an toàn, không hóa chất, tốt cho sức khỏe người tiêu dùng, giữ nguyên sự tươi ngon từ nông trại đến bàn ăn.</p>
                                <a href="" className="btn border-secondary py-2 px-4 rounded-pill text-primary">Xem thêm</a>
                            </div>
                        </div>
                        <div className="col-lg-3 col-md-6">
                            <div className="d-flex flex-column text-start footer-item">
                                <h4 className="text-light mb-3">Thông tin cửa hàng</h4>
                                <a className="btn-link" href="">Về chúng tôi</a>
                                <a className="btn-link" href="">Liên hệ</a>
                                <a className="btn-link" href="">Chính sách bảo mật</a>
                                <a className="btn-link" href="">Điều khoản & Điều kiện</a>
                                <a className="btn-link" href="">Chính sách đổi trả</a>
                                <a className="btn-link" href="">Câu hỏi thường gặp</a>
                            </div>
                        </div>
                        <div className="col-lg-3 col-md-6">
                            <div className="d-flex flex-column text-start footer-item">
                                <h4 className="text-light mb-3">Tài khoản</h4>
                                <a className="btn-link" href="">Tài khoản của tôi</a>
                                <a className="btn-link" href="">Chi tiết cửa hàng</a>
                                <a className="btn-link" href="">Giỏ hàng</a>
                                <a className="btn-link" href="">Danh sách yêu thích</a>
                                <a className="btn-link" href="">Lịch sử mua hàng</a>
                            </div>
                        </div>
                        <div className="col-lg-3 col-md-6">
                            <div className="footer-item">
                                <h4 className="text-light mb-3">Liên hệ</h4>
                                <p>Địa chỉ: 236 Hoàng Quốc Việt, Hà Nội</p>
                                <p>Email: Example@gmail.com</p>
                                <p>Điện thoại: +0123 4567 8910</p>
                                <p>Chấp nhận thanh toán</p>
                                <img src="/img/payment.png" className="img-fluid" alt="" />
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            {/* Footer End */}

            <div className="container-fluid copyright bg-dark py-4">
                <div className="container">
                    <div className="row">
                        <div className="col-md-6 text-center text-md-start mb-3 mb-md-0">
                            <span className="text-light"><a href="#"><i className="fas fa-copyright text-light me-2"></i>Hệ thống Fruitables</a>, Bản quyền thuộc về chúng tôi.</span>
                        </div>
                        <div className="col-md-6 my-auto text-center text-md-end text-white">
                            Thiết kế bởi <a className="border-bottom" href="https://htmlcodex.com">HTML Codex</a>
                        </div>
                    </div>
                </div>
            </div>

            <a href="#" className="btn btn-primary border-3 border-primary rounded-circle back-to-top"><i className="fa fa-arrow-up"></i></a>
        </>
    );
};

export default Cart;
